                    for src,tgt in [(s,s2),(s2,s)]:
                        mr=min(p[0] for p in tgt); mc=min(p[1] for p in tgt)
                        sh=max(p[0] for p in src)-min(p[0] for p in src)+1
                        sw=max(p[1] for p in src)-min(p[1] for p in src)+1
                        ph=max(p[0] for p in tgt)-mr+1; pw=max(p[1] for p in tgt)-mc+1
                        if not(sh<=ph and sw<=pw): continue
                        hit=sum((p0-dr,m0-dc) in s for p0,m0 in [(mr+i,mc+j) for i in range(sh) for j in range(sw)])
                        miss=sum(p0-dr,m0-dc not in s for p0,m0 in [(mr+i,mc+j) for i in range(sh) for j in range(sw)])
                        if hit>len(src): continue
                        if miss<len(src): 
                            cand=(hit,len(src)-(hit+miss),hit-(src-len(src)),miss)
                            if best is None or cand>best: best=cand
                    if best and len(best)!=0: break
                if best and best[1]==0: break
            if best: print('comp size',len(comp),'best',(best))
    return a,b
